#include <iostream>
#include <vector>
using namespace std;

int main() {
    int n;
    cin >> n;
    const long long MOD = 1000000007;
    vector<long long> inv(n + 2, 0);
    inv[1] = 1;
    long long h = 1;
    for (int i = 2; i <= n; i++) {
        inv[i] = (MOD - (MOD / i) * inv[MOD % i] % MOD) % MOD;
        h = (h + inv[i]) % MOD;
    }
    cout << (long long)n % MOD * h % MOD << '\n';
    return 0;
}

